 "settings": {"notes":"","dinnerTime":"18:30","minutes":{"mon":45,"tue":45,"wed":45,"thu":45,"fri":45,"sat":120,"sun":120},"equipment":["pressure cooker"],"mealRule":"veg+carb"}
}$seed$;
  hid uuid;
  r jsonb;
  rid uuid;
begin
  insert into public.ingredients (slug, name, section)
  select i->>'slug', i->>'name', i->>'section'
  from jsonb_array_elements(seed->'ingredients') i
  on conflict do nothing;

  if target is not null then
    hid := target;
  else
    select case when count(distinct household_id) = 1 then min(household_id::text)::uuid end
      into hid
      from public.household_members where role = 'owner';
    if hid is null and exists (select 1 from public.household_members where role = 'owner') then
      raise exception 'More than one owner household: set target in this script';
    end if;
  end if;

  if hid is null then
    raise notice 'No household yet: loaded ingredients only. Re-run after creating the household.';
    return;
  end if;

  insert into public.household_settings (household_id, settings)
  values (hid, seed->'settings')
  on conflict (household_id) do update
    set settings = (seed->'settings') || public.household_settings.settings;

  for r in select * from jsonb_array_elements(seed->'recipes') loop
    rid := null;
    insert into public.recipes as t (household_id, slug, name, course, serves, active_mins, total_mins,
                                     provides, spice, tags, source, rating, notes, is_example)
    values (hid, r->>'slug', r->>'name', r->>'course', (r->>'serves')::numeric,
            (r->>'active_mins')::integer, (r->>'total_mins')::integer,
            array(select jsonb_array_elements_text(r->'provides')), (r->>'spice')::smallint,
            array(select jsonb_array_elements_text(r->'tags')), r->>'source',
            (r->>'rating')::smallint, r->>'notes', true)
    on conflict (household_id, slug) do update
      set name = excluded.name, course = excluded.course, serves = excluded.serves,
          active_mins = excluded.active_mins, total_mins = excluded.total_mins,
          provides = excluded.provides, spice = excluded.spice, tags = excluded.tags,
          source = excluded.source
      where t.is_example
    returning id into rid;

    continue when rid is null;  -- kept by the household; leave it alone

    delete from public.recipe_ingredients where recipe_id = rid;
    insert into public.recipe_ingredients (recipe_id, position, ingredient_slug, qty, unit, note)
    select rid, n - 1, g.slug, (i->>'qty')::numeric, i->>'unit', i->>'note'
    from jsonb_array_elements(r->'ingredients') with ordinality as x(i, n)
    join public.ingredients g on g.name = i->>'name';

    delete from public.recipe_steps where recipe_id = rid;
    insert into public.recipe_steps (recipe_id, position, text, timer_mins)
    select rid, n - 1, s->>'text', (s->>'timer_mins')::integer
    from jsonb_array_elements(r->'steps') with ordinality as x(s, n);
  end loop;
end
$do$;
